18	const EXAMPLES = [
19	  "A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.",
20	  "Arrows that explode on impact without breaking blocks, with a 5 second cooldown per player.",
21	  "Right-clicking with a blaze rod shoots a fireball where you look.",
