24	const STEP_DETAIL = {
25	  spec: "Turn the idea into a plugin spec and an in-game test plan",
26	  repo: "Create the mod repository with Entire and Neatlogs hooks",
27	  build: "Write the Paper plugin",
28	  compile: "Package it with Maven",
29	  deploy: "Load it on the Paper server",
30	  playtest: "An AI player runs every check in-game",
31	  fix: "Patch failures from the evidence, up to 3 attempts",
32	  done: "Report the result",
