35	export default function BuildPage({ mod, running, lessons, onCreated, onWatch, onNew, onOpenCode }) {
36	  const [prompt, setPrompt] = React.useState("");
37	  return (
38	    <div className="build-chat">
39	      <section className="chat">
40	        <ChatHead mod={mod} onNew={onNew} onOpenCode={onOpenCode} />
41	        {mod ? <Thread mod={mod} onOpenCode={onOpenCode} /> : <Welcome lessons={lessons} onPick={setPrompt} />}
42	        <Composer
43	          mod={mod}
44	          running={running}
45	          prompt={prompt}
46	          setPrompt={setPrompt}
47	          onCreated={onCreated}
48	          onWatch={onWatch}
49	        />
50	      </section>
51	      <TestPanel mod={mod} building={Boolean(running)} />
52	    </div>
53	  );
54	}
