56	function ChatHead({ mod, onNew, onOpenCode }) {
57	  return (
58	    <header className="chat-head">
59	      <div className="chat-title">
60	        {mod ? (
61	          <>
62	            <strong>{mod.name}</strong>
63	            <Status status={mod.running ? "running" : mod.status} />
64	            {mod.seed && <span className="tag">Seeded bug</span>}
65	          </>
66	        ) : (
67	          <strong>New mod</strong>
68	        )}
69	      </div>
70	      {mod && (
71	        <div className="page-actions">
72	          {mod.running && (
73	            <button className="btn danger sm" onClick={() => call("studio:stop", { id: mod.id })}>
74	              <Icon name="stop" size={13} />
75	              Stop
76	            </button>
77	          )}
78	          {mod.repoDir && (
79	            <button className="btn sm" onClick={() => onOpenCode(mod.id)}>
80	              <Icon name="code" size={13} />
81	              Code
82	            </button>
83	          )}
84	          {!mod.running && (
85	            <button className="btn sm" onClick={onNew}>
86	              <Icon name="plus" size={13} />
87	              New
88	            </button>
89	          )}
90	        </div>
91	      )}
92	    </header>
93	  );
94	}
