96	function Welcome({ lessons, onPick }) {
97	  return (
98	    <div className="thread welcome-wrap">
99	      <div className="intro">
100	        <span className="welcome-mark">B</span>
101	        <h1>What should your mod do?</h1>
102	        <p>Describe a gameplay idea. Benana writes the Paper plugin, an AI player tests it on a live server, and a fixer patches anything that breaks.</p>
103	        <div className="ideas">
104	          {EXAMPLES.map((ex) => (
105	            <button key={ex} onClick={() => onPick(ex)}>
106	              <Icon name="spark" size={14} />
107	              <span>{ex}</span>
108	            </button>
109	          ))}
110	        </div>
111	        {lessons.length > 0 && (
112	          <div className="welcome-lessons">
113	            <span className="side-label">
114	              The fixer has learned {lessons.length} lesson{lessons.length === 1 ? "" : "s"}
115	            </span>
116	            <p>{lessons.at(-1).lesson}</p>
117	          </div>
118	        )}
119	      </div>
120	    </div>
121	  );
122	}
