124	function Composer({ mod, running, prompt, setPrompt, onCreated, onWatch }) {
125	  const [seed, setSeed] = React.useState(false);
126	  const [busy, setBusy] = React.useState(false);
127	  const [error, setError] = React.useState("");
128	  const ref = React.useRef(null);
129	  const canStart = !busy && !running && (seed || prompt.trim().length >= 8);
130	
131	  React.useLayoutEffect(() => {
132	    const el = ref.current;
133	    if (!el) return;
134	    el.style.height = "auto";
135	    el.style.height = `${Math.min(el.scrollHeight, 180)}px`;
136	  }, [prompt]);
137	
138	  const start = async () => {
139	    if (!canStart) return;
140	    setBusy(true);
141	    setError("");
142	    try {
143	      const created = await call("studio:create", { prompt, seed });
144	      setPrompt("");
145	      onCreated(created.id);
146	    } catch (e) {
147	      setError(e.message);
148	    } finally {
149	      setBusy(false);
150	    }
151	  };
152	
153	  return (
154	    <div className="composer-wrap">
155	      {mod?.running && <Dock mod={mod} />}
156	      {running && running.id !== mod?.id && (
157	        <button className="dock dock-link" onClick={() => onWatch(running.id)}>
158	          <span className="spinner" />
159	          <span>
160	            <strong>{running.name}</strong> is building
161	          </span>
162	          <span className="dock-cta">
163	            Watch <Icon name="arrow" size={13} />
164	          </span>
165	        </button>
166	      )}
167	      {error && <div className="alert">{error}</div>}
168	      <div className={`chat-input ${seed ? "seeded" : ""} ${running ? "locked" : ""}`}>
169	        <textarea
170	          ref={ref}
171	          rows={1}
172	          value={prompt}
173	          disabled={seed}
174	          aria-label="Describe a mod"
175	          placeholder={
176	            running ? "One mod builds at a time. Describe the next one…" : mod ? "Describe another mod…" : "A golden sword that launches mobs into the sky…"
177	          }
178	          onChange={(e) => setPrompt(e.target.value)}
179	          onKeyDown={(e) => {
180	            if (e.key === "Enter" && !e.shiftKey) {
181	              e.preventDefault();
182	              start();
183	            }
184	          }}
185	        />
186	        <div className="chat-input-bar">
187	          <label className="toggle" title="Attempt 1 starts from a labeled buggy fixture. The playtester and fixer still run for real.">
188	            <input type="checkbox" checked={seed} onChange={(e) => setSeed(e.target.checked)} />
189	            <span className="switch" />
190	            Seeded bug
191	          </label>
192	          <span className="input-hint">{running ? "Waiting for the current build" : "Enter to build · Shift+Enter for a new line"}</span>
193	          <button className="send" disabled={!canStart} onClick={start} aria-label="Build and playtest" title="Build and playtest">
194	            {busy ? <span className="spinner dark" /> : <Icon name="send" size={16} />}
195	          </button>
196	        </div>
197	      </div>
198	    </div>
199	  );
200	}
