202	function Dock({ mod }) {
203	  const now = useNow(true);
204	  const i = phaseIndex(mod);
205	  const label = PHASES[i]?.[1] || "Working";
206	  const verdict = latestVerdict(mod);
207	  const total = mod.testPlan?.checks.length || 0;
208	  const done = (verdict?.checks || []).length;
209	  const attempt = mod.attempts.at(-1);
210	  const since = attempt?.startedAt || mod.updatedAt || mod.createdAt;
211	  const who =
212	    mod.phase === "playtest" ? "The AI player is testing in-game" : mod.phase === "fix" ? "The fixer is patching the plugin" : `${label} in progress`;
213	  return (
214	    <div className="dock">
215	      <span className="spinner" />
216	      <span className="dock-text">
217	        <strong>{who}</strong>
218	        <small>
219	          Step {i + 1} of {PHASES.length} · {label}
220	          {attempt ? ` · attempt ${attempt.n}` : ""}
221	        </small>
222	      </span>
223	      {total > 0 && (
224	        <span className="dock-checks">
225	          {done}/{total} checks
226	        </span>
227	      )}
228	      <span className="dock-time">{fmtDuration(now - since)}</span>
229	    </div>
230	  );
231	}
