235	function useFeed(mod) {
236	  const [feed, setFeed] = React.useState([]);
237	  const idRef = React.useRef(mod.id);
238	  idRef.current = mod.id;
239	  React.useEffect(
240	    () =>
241	      on("studio:feed", ({ modId, item }) => {
242	        if (modId === idRef.current) setFeed((prev) => [...prev.slice(-799), item]);
243	      }),
244	    [],
245	  );
246	  React.useEffect(() => {
247	    setFeed([]);
248	    call("studio:get", { id: mod.id })
249	      .then((full) => setFeed(full.feed.slice(-800)))
250	      .catch(() => {});
251	  }, [mod.id]);
252	  return feed;
253	}
254	
255	function buildThread(mod, feed) {
256	  const items = [{ type: "user", key: "user" }, { type: "plan", key: "plan" }];
257	  let turn = null;
258	  feed.forEach((f, i) => {
259	    const key = `${f.at}-${i}`;
260	    if (f.kind === "session") return;
261	    if (f.role === "benana") {
262	      turn = null;
263	      if (f.kind === "phase") items.push({ type: "phase", key, f });
264	      else if (f.kind === "failure" || f.kind === "error") items.push({ type: "alert", key, f });
265	      else items.push({ type: "note", key, f });
266	      return;
267	    }
268	    if (f.kind === "plan") {
269	      items.push({ type: "testplan", key, bare: turn?.role === "spec" });
270	      turn = null;
271	      return;
272	    }
273	    const id = `${f.role}:${f.attempt || 0}`;
274	    if (!turn || turn.id !== id) {
275	      turn = { type: "turn", key, id, role: f.role, attempt: f.attempt || null, entries: [] };
276	      items.push(turn);
277	    }
278	    turn.entries.push(f);
279	  });
280	  if (!feed.some((f) => f.kind === "plan") && mod.testPlan) items.splice(2, 0, { type: "testplan", key: "tp" });
281	  if (!mod.running && ["passed", "failed", "stopped"].includes(mod.status)) items.push({ type: "result", key: "result" });
282	  return items;
283	}
284	
285	function Thread({ mod, onOpenCode }) {
286	  const feed = useFeed(mod);
287	  const items = React.useMemo(() => buildThread(mod, feed), [mod, feed]);
288	  const { ref, onScroll, away, jump } = useStickyScroll(`${items.length}:${feed.length}:${mod.updatedAt}`);
289	  const lastTurn = [...items].reverse().find((x) => x.type === "turn");
290	
291	  return (
292	    <div className="thread" ref={ref} onScroll={onScroll}>
293	      <div className="thread-inner">
294	        {items.map((it) => {
295	          switch (it.type) {
296	            case "user":
297	              return (
298	                <div key={it.key} className="msg-user">
299	                  <div className="bubble">{mod.prompt}</div>
300	                </div>
301	              );
302	            case "plan":
303	              return (
304	                <Turn key={it.key} role="benana" title="Benana" meta="Plan">
305	                  <p className="prose">I'll build this as a Paper plugin and test it with an AI player. This list updates as each step finishes.</p>
306	                  <PipelineChecklist mod={mod} />
307	                </Turn>
308	              );
309	            case "testplan":
310	              return <TestPlanChecklist key={it.key} mod={mod} bare={it.bare} />;
311	            case "phase":
312	              return <PhaseLine key={it.key} f={it.f} mod={mod} />;
313	            case "note":
314	              return (
315	                <div key={it.key} className={`note-line ${/Entire checkpoint/.test(it.f.text) ? "entire" : ""}`}>
316	                  <Icon name="info" size={13} />
317	                  <span>{it.f.text}</span>
318	                </div>
319	              );
320	            case "alert":
321	              return (
322	                <div key={it.key} className="alert-card">
323	                  <CheckIcon status="fail" />
324	                  <div>
325	                    <strong>{it.f.kind === "error" ? "Run error" : `Attempt ${it.f.attempt} failed`}</strong>
326	                    <p>{it.f.text.replace(/^Attempt \d+ failed \(\w+\): /, "")}</p>
327	                  </div>
328	                </div>
329	              );
330	            case "turn":
331	              return <AgentTurn key={it.key} turn={it} mod={mod} live={mod.running && it === lastTurn} />;
332	            case "result":
333	              return <ResultCard key={it.key} mod={mod} onOpenCode={onOpenCode} />;
334	            default:
335	              return null;
336	          }
337	        })}
338	      </div>
339	      {away && (
340	        <button className="jump" onClick={jump}>
341	          Jump to latest
342	        </button>
343	      )}
344	    </div>
345	  );
346	}
