348	const AVATAR = { benana: "B", spec: "S", builder: "Bu", playtester: "P", fixer: "F" };
349	
350	function Turn({ role, title, meta, children }) {
351	  return (
352	    <div className="turn">
353	      <div className="turn-head">
354	        <span className={`role-avatar ${role}`}>{AVATAR[role] || role[0]?.toUpperCase()}</span>
355	        <strong>{title}</strong>
356	        {meta && <span className="meta">{meta}</span>}
357	      </div>
358	      <div className="turn-body">{children}</div>
359	    </div>
360	  );
361	}
362	
363	function sessionFor(mod, role, attemptN) {
364	  if (role === "spec") return mod.sessions.find((s) => s.role === "spec");
365	  const a = mod.attempts.find((x) => x.n === attemptN);
366	  return a?.sessions.filter((s) => s.role === role).at(-1);
367	}
368	
369	function AgentTurn({ turn, mod, live }) {
370	  const s = sessionFor(mod, turn.role, turn.attempt);
371	  const meta = [
372	    turn.attempt ? `attempt ${turn.attempt}` : null,
373	    s?.model ? shortModel(s.model) : null,
374	    s?.endedAt && s?.startedAt ? fmtDuration(s.endedAt - s.startedAt) : null,
375	    s?.usage?.costUsd ? fmtMoney(s.usage.costUsd) : null,
376	  ]
377	    .filter(Boolean)
378	    .join(" · ");
379	
380	  const groups = [];
381	  for (const e of turn.entries) {
382	    const isWork = e.kind === "tool" || e.kind === "result" || e.kind === "note";
383	    const last = groups.at(-1);
384	    if (isWork && last?.work) last.entries.push(e);
385	    else if (isWork) groups.push({ work: true, entries: [e] });
386	    else groups.push({ work: false, entries: [e] });
387	  }
388	
389	  return (
390	    <Turn role={turn.role} title={ROLE[turn.role] || turn.role} meta={meta}>
391	      {groups.map((g, i) =>
392	        g.work ? (
393	          <WorkLog key={i} entries={g.entries} mod={mod} live={live && i === groups.length - 1} />
394	        ) : (
395	          <Markdown key={i} text={g.entries[0].text} />
396	        ),
397	      )}
398	    </Turn>
399	  );
400	}
401	
402	function parseSummary(summary) {
403	  if (!summary) return {};
404	  try {
405	    return JSON.parse(summary);
406	  } catch {
407	    const pick = (k) => summary.match(new RegExp(`"${k}":"([^"]*)"`))?.[1];
408	    return { id: pick("id"), status: pick("status"), observed: pick("observed"), file_path: pick("file_path"), command: pick("command") };
409	  }
410	}
411	
412	const TOOL_ICON = {
413	  Read: "file",
414	  Write: "file",
415	  Edit: "file",
416	  MultiEdit: "file",
417	  Bash: "terminal",
418	  Grep: "search",
419	  Glob: "search",
420	};
421	
422	function describeArgs(name, summary) {
423	  const args = parseSummary(summary);
424	  if (args.file_path) return args.file_path.replace(/\\/g, "/");
425	  if (args.command) return args.command;
426	  if (args.pattern) return args.pattern;
427	  if (typeof args === "object" && args && Object.keys(args).length) {
428	    return Object.entries(args)
429	      .filter(([, v]) => v != null && v !== "")
430	      .map(([k, v]) => `${k} ${typeof v === "object" ? JSON.stringify(v) : v}`)
431	      .join(" · ")
432	      .slice(0, 160);
433	  }
434	  return summary || "";
435	}
436	
437	function WorkLog({ entries, mod, live }) {
438	  const rows = entries.filter((e) => e.kind !== "result" || e.isError || e.name !== "report_check");
439	  const [open, setOpen] = React.useState(false);
440	  const LIMIT = 4;
441	  const hidden = !open && rows.length > LIMIT + 1 ? rows.length - LIMIT : 0;
442	  const shown = hidden ? rows.slice(-LIMIT) : rows;
443	  const titles = new Map((mod.testPlan?.checks || []).map((c) => [c.id, c.title]));
444	
445	  return (
446	    <div className={`worklog ${live ? "live" : ""}`}>
447	      {hidden > 0 && (
448	        <button className="worklog-more" onClick={() => setOpen(true)}>
449	          {hidden} earlier action{hidden === 1 ? "" : "s"}
450	        </button>
451	      )}
452	      {shown.map((e, i) => {
453	        if (e.kind === "tool" && e.name === "report_check") {
454	          const a = parseSummary(e.summary);
455	          return (
456	            <div key={i} className="work-row check">
457	              <CheckIcon status={a.status} />
458	              <span>
459	                Reported <strong>{titles.get(a.id) || a.id}</strong>
460	                {a.status ? ` · ${a.status}` : ""}
461	              </span>
462	            </div>
463	          );
464	        }
465	        if (e.kind === "tool" && e.name === "finish") {
466	          return (
467	            <div key={i} className="work-row check">
468	              <CheckIcon status="pass" />
469	              <span>Finished the playtest</span>
470	            </div>
471	          );
472	        }
473	        if (e.kind === "result") {
474	          return (
475	            <div key={i} className={`work-row result ${e.isError ? "error" : ""}`}>
476	              <span className="work-arrow">↳</span>
477	              <span className="work-out">{e.text.slice(0, 220)}</span>
478	            </div>
479	          );
480	        }
481	        if (e.kind === "note") {
482	          return (
483	            <div key={i} className="work-row note">
484	              <Icon name="info" size={13} />
485	              <span>{e.text}</span>
486	            </div>
487	          );
488	        }
489	        const isLast = live && i === shown.length - 1;
490	        return (
491	          <div key={i} className="work-row">
492	            {isLast ? <span className="spinner" /> : <Icon name={TOOL_ICON[e.name] || "game"} size={13} />}
493	            <code>{e.name}</code>
494	            <span className="work-args">{describeArgs(e.name, e.summary)}</span>
495	          </div>
496	        );
497	      })}
498	    </div>
499	  );
500	}
501	
502	function PhaseLine({ f, mod }) {
503	  const current = mod.running && mod.phase === f.phase && phaseIndex(mod) === PHASES.findIndex(([k]) => k === f.phase);
504	  return (
505	    <div className={`phase-line ${current ? "current" : ""}`}>
506	      {current ? <span className="spinner" /> : <CheckIcon status="pass" />}
507	      <span>{f.text}</span>
508	    </div>
509	  );
510	}
511	
512	function PipelineChecklist({ mod }) {
513	  const current = phaseIndex(mod);
514	  const passed = mod.status === "passed";
515	  const failed = ["failed", "stopped"].includes(mod.status);
516	  const fixSkipped = passed && !mod.attempts.some((a) => a.role === "fixer");
517	  const doneCount = PHASES.filter((_, i) => passed || i < current).length;
518	  return (
519	    <div className="checklist">
520	      <div className="checklist-head">
521	        <strong>Build plan</strong>
522	        <span className="meta">
523	          {doneCount}/{PHASES.length}
524	        </span>
525	      </div>
526	      <ul>
527	        {PHASES.map(([key, label], i) => {
528	          let state = i < current ? "done" : i === current ? (failed ? "failed" : mod.running ? "active" : "done") : "todo";
529	          if (passed) state = "done";
530	          if (key === "fix" && fixSkipped) state = "skipped";
531	          return (
532	            <li key={key} className={state}>
533	              <StepIcon state={state} />
534	              <span className="step-label">{label}</span>
535	              <span className="step-detail">{state === "skipped" ? "Not needed, passed first try" : STEP_DETAIL[key]}</span>
536	            </li>
537	          );
538	        })}
539	      </ul>
540	    </div>
541	  );
542	}
543	
544	function StepIcon({ state }) {
545	  if (state === "active") return <span className="step-icon active"><span className="spinner" /></span>;
546	  if (state === "done") return <span className="step-icon done"><Icon name="check" size={11} /></span>;
547	  if (state === "failed") return <span className="step-icon failed"><Icon name="x" size={11} /></span>;
548	  if (state === "skipped") return <span className="step-icon skipped" />;
549	  return <span className="step-icon" />;
550	}
551	
552	function TestPlanChecklist({ mod, bare }) {
553	  const verdict = latestVerdict(mod);
554	  const byId = new Map((verdict?.checks || []).map((c) => [c.id, c]));
555	  const checks = mod.testPlan?.checks || [];
556	  const testing = mod.running && mod.phase === "playtest";
557	  const nextId = testing ? checks.find((c) => !byId.has(c.id))?.id : null;
558	  const passing = checks.filter((c) => byId.get(c.id)?.status === "pass").length;
559	  if (!checks.length) return null;
560	  const list = (
561	      <div className="checklist">
562	        <div className="checklist-head">
563	          <strong>Test plan</strong>
564	          <span className="meta">
565	            {passing}/{checks.length} passing
566	          </span>
567	        </div>
568	        <ul>
569	          {checks.map((c) => {
570	            const r = byId.get(c.id);
571	            const state = r ? (r.status === "pass" ? "done" : r.status === "fail" ? "failed" : "blocked") : c.id === nextId ? "active" : "todo";
572	            return (
573	              <li key={c.id} className={`${state} tall`}>
574	                {state === "blocked" ? <CheckIcon status="blocked" /> : <StepIcon state={state} />}
575	                <span className="step-label">{c.title}</span>
576	                <span className="step-detail">{r?.observed || c.expect}</span>
577	              </li>
578	            );
579	          })}
580	        </ul>
581	      </div>
582	  );
583	  if (bare) return <div className="turn-cont">{list}</div>;
584	  return (
