654	function Markdown({ text }) {
655	  const blocks = String(text || "")
656	    .replace(/\s+-\s+(?=\*\*)/g, "\n- ")
657	    .split(/\n{2,}/);
658	  return (
659	    <div className="prose">
660	      {blocks.map((block, i) => {
661	        const lines = block.split("\n").filter((l) => l.trim());
662	        const bullets = lines.filter((l) => /^\s*([-*]|\d+\.)\s+/.test(l));
663	        if (bullets.length && bullets.length === lines.length) {
664	          return (
665	            <ul key={i}>
666	              {lines.map((l, j) => (
667	                <li key={j}>{inline(l.replace(/^\s*([-*]|\d+\.)\s+/, ""))}</li>
668	              ))}
669	            </ul>
670	          );
671	        }
672	        if (bullets.length && !/^\s*([-*]|\d+\.)\s+/.test(lines[0])) {
673	          return (
674	            <React.Fragment key={i}>
675	              <p>{inline(lines[0])}</p>
676	              <ul>
677	                {lines.slice(1).map((l, j) => (
678	                  <li key={j}>{inline(l.replace(/^\s*([-*]|\d+\.)\s+/, ""))}</li>
679	                ))}
680	              </ul>
681	            </React.Fragment>
682	          );
683	        }
684	        return (
685	          <p key={i}>
686	            {lines.map((l, j) => (
687	              <React.Fragment key={j}>
688	                {j > 0 && <br />}
689	                {inline(l)}
690	              </React.Fragment>
691	            ))}
692	          </p>
693	        );
694	      })}
695	    </div>
696	  );
697	}
