100	// Runs one agent session for a mod and records it on the attempt.
101	async function agent(mod, attempt, role, options) {
102	  const session = { role, model: options.model, startedAt: now(), sessionId: null };
103	  if (attempt) attempt.sessions.push(session);
104	  else mod.sessions.push(session);
105	  save(mod);
106	  const handle = runClaude({
107	    ...options,
108	    onEvent: (ev) => {
109	      if (ev.kind === 'session') { session.sessionId = ev.sessionId; save(mod); return; }
110	      feed(mod, { attempt: attempt?.n ?? 0, role, ...ev, input: undefined });
111	      if (role === 'playtester' && ev.kind === 'tool') emit('studio:playtester', { modId: mod.id, tool: ev.name, input: ev.input });
112	    },
113	  });
114	  active.stop = handle.stop;
115	  const result = await handle.done;
116	  Object.assign(session, { endedAt: now(), ok: result.ok, error: result.error, usage: result.usage, sessionId: result.sessionId || session.sessionId });
117	  save(mod);
118	  if (active?.stopped) throw new Error('Stopped by user.');
119	  return result;
120	}
