212	async function runAttempt(mod, n, previous) {
213	  const attempt = { n, role: n === 1 ? (mod.seed ? 'seeded' : 'builder') : 'fixer', status: 'running', startedAt: now(), sessions: [] };
214	  mod.attempts.push(attempt);
215	  save(mod);
216	
217	  setPhase(mod, n === 1 ? 'build' : 'fix', n === 1 ? `Attempt 1: writing ${mod.name}` : `Attempt ${n}: fixing what the playtester found`);
218	  await codePhase(mod, attempt, previous);
219	
220	  setPhase(mod, 'compile', `Attempt ${n}: compiling with Maven`);
221	  attempt.build = await repo.build(mod.repoDir, mod.name);
222	  if (!attempt.build.ok) {
223	    attempt.failure = { kind: 'build', summary: 'The plugin did not compile.' };
224	    attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): build failed`);
225	    return attempt;
226	  }
227	  attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): ${attempt.role === 'fixer' ? 'fix from playtest evidence' : 'implement'} ${mod.name}`);
228	  feed(mod, { attempt: n, role: 'benana', kind: 'note', text: `Committed ${attempt.commit.sha.slice(0, 7)}${attempt.commit.checkpoint ? `, Entire checkpoint ${attempt.commit.checkpoint}` : ''}` });
