239	  const tally = attempt.verdict.checks.map((c) => `${c.id}=${c.status}`).join(', ');
240	  attempt.playtestCommit = await repo.commit(mod.repoDir, `Playtest attempt ${n}: ${attempt.verdict.passed ? 'PASS' : 'FAIL'}${tally ? ` (${tally})` : ''}`);
