254	      setPhase(mod, 'game', 'Starting the Minecraft server');
255	      await game.start(emit);
256	    }
257	    mod.status = 'running';
258	    setPhase(mod, 'spec', 'Writing the spec and an in-game test plan');
259	    const spec = await specPhase(mod);
260	    mod.name = spec.modName;
261	    mod.spec = { summary: spec.summary, behavior: spec.behavior || [] };
262	    mod.testPlan = spec.testPlan;
263	    feed(mod, { role: 'spec', kind: 'plan', text: `${mod.testPlan.checks.length} checks: ${mod.testPlan.checks.map((c) => c.title).join(' · ')}` });
264	
265	    setPhase(mod, 'repo', 'Creating the mod repository with Entire and Neatlogs hooks');
266	    const created = await repo.create({ slug: `${slugify(mod.name)}-${mod.id.slice(-4)}`, name: mod.name, summary: mod.spec.summary });
267	    mod.repoDir = created.dir;
268	    mod.partners = created.partners;
269	    fs.mkdirSync(path.join(mod.repoDir, 'playtest'), { recursive: true });
270	    fs.writeFileSync(path.join(mod.repoDir, 'playtest', 'test-plan.json'), JSON.stringify(mod.testPlan, null, 2));
271	    await repo.commit(mod.repoDir, 'Add the in-game test plan');
272	    save(mod);
273	
274	    let previous = null;
275	    for (let n = 1; n <= MAX_ATTEMPTS; n++) {
276	      const attempt = await runAttempt(mod, n, previous);
277	      attempt.status = attempt.failure ? 'failed' : 'passed';
278	      attempt.endedAt = now();
279	      save(mod);
280	      if (!attempt.failure) {
281	        mod.status = 'passed';
282	        if (attempt.lesson) addLesson(attempt.lesson, mod);
283	        setPhase(mod, 'done', n === 1 ? `${mod.name} passed every check on the first attempt` : `${mod.name} passed after ${n} attempts`);
284	        return;
285	      }
