1	// Runs one headless Claude Code session and streams its activity.
2	// Sessions run inside the mod repo so the repo's Entire and Neatlogs hooks capture them.
3	const { spawnExecutable, terminateProcessTree } = require('../processes.cjs');
4	const { normalizeUsage } = require('../providers.cjs');
5	
6	const MODELS = { build: 'opus', playtest: 'sonnet' };
7	
8	function summarize(input) {
9	  const text = JSON.stringify(input ?? {});
10	  return text.length > 240 ? `${text.slice(0, 240)}…` : text;
11	}
12	
13	function resultText(content) {
14	  if (typeof content === 'string') return content;
15	  if (Array.isArray(content)) return content.map((c) => c.text || '').join('\n');
16	  return JSON.stringify(content ?? '');
17	}
18	
19	/**
20	 * @returns {{ done: Promise<{ok, sessionId, final, usage, error}>, stop: () => void }}
21	 */
22	function runClaude({ cwd, prompt, model, tools, allowedTools = [], mcpConfigFile, appendSystemPrompt, timeoutMs = 20 * 60 * 1000, onEvent = () => {} }) {
23	  const args = ['-p', '--output-format', 'stream-json', '--verbose', '--model', model, '--permission-mode', 'acceptEdits', '--setting-sources', 'project,local'];
24	  if (tools) args.push('--tools', tools.join(','));
25	  if (allowedTools.length) args.push('--allowedTools', allowedTools.join(','));
26	  if (mcpConfigFile) args.push('--mcp-config', mcpConfigFile, '--strict-mcp-config');
27	  if (appendSystemPrompt) args.push('--append-system-prompt', appendSystemPrompt);
28	
29	  const env = { ...process.env };
30	  delete env.ELECTRON_RUN_AS_NODE;
31	  const child = spawnExecutable('claude', args, { cwd, stdio: ['pipe', 'pipe', 'pipe'], env });
32	  const run = { sessionId: null, final: '', usage: null, error: null, stopped: false };
33	  const names = new Map();
34	
35	  const done = new Promise((resolve) => {
36	    let buf = '';
37	    let stderr = '';
38	    const timer = setTimeout(() => { run.error = `Timed out after ${Math.round(timeoutMs / 60000)} minutes.`; terminateProcessTree(child); }, timeoutMs);
39	    const handle = (line) => {
40	      let ev;
41	      try { ev = JSON.parse(line); } catch { return; }
42	      if (ev.type === 'system' && ev.session_id) {
43	        if (!run.sessionId) onEvent({ kind: 'session', sessionId: ev.session_id, model });
44	        run.sessionId = ev.session_id;
45	      } else if (ev.type === 'assistant') {
46	        for (const item of ev.message?.content || []) {
47	          if (item.type === 'text' && item.text.trim()) onEvent({ kind: 'text', text: item.text.trim() });
48	          if (item.type === 'tool_use') {
49	            names.set(item.id, item.name);
50	            onEvent({ kind: 'tool', name: item.name.replace(/^mcp__\w+?__/, ''), input: item.input, summary: summarize(item.input) });
51	          }
52	        }
53	      } else if (ev.type === 'user') {
54	        for (const item of ev.message?.content || []) {
55	          if (item.type !== 'tool_result') continue;
56	          const name = (names.get(item.tool_use_id) || 'tool').replace(/^mcp__\w+?__/, '');
57	          onEvent({ kind: 'result', name, isError: Boolean(item.is_error), text: resultText(item.content).slice(0, 1500) });
58	        }
59	      } else if (ev.type === 'result') {
60	        run.final = ev.result || '';
61	        run.usage = normalizeUsage(ev.usage, ev);
62	        if (ev.is_error) run.error = String(ev.result || 'Claude reported an error.');
63	      }
64	    };
65	    child.stdout.on('data', (d) => {
66	      buf += d;
67	      const lines = buf.split(/\r?\n/);
68	      buf = lines.pop();
69	      lines.filter(Boolean).forEach(handle);
70	    });
71	    child.stderr.on('data', (d) => { stderr = (stderr + d).slice(-4000); });
72	    child.on('error', (e) => { run.error = `Could not start Claude Code: ${e.message}`; });
73	    child.on('close', (code) => {
74	      clearTimeout(timer);
75	      if (buf.trim()) handle(buf);
76	      if (run.stopped) run.error = 'Stopped.';
77	      else if (code !== 0 && !run.error) run.error = stderr.trim() || `Claude exited with code ${code}.`;
78	      resolve({ ok: !run.error, sessionId: run.sessionId, final: run.final, usage: run.usage, error: run.error });
79	    });
80	  });
81	
82	  child.stdin.end(prompt);
83	  return { done, stop: () => { run.stopped = true; terminateProcessTree(child); } };
84	}
85	
86	module.exports = { runClaude, MODELS };
