// Temporary visual harness: the real ModStudio against a fake bridge that mimics the backend's multi-turn behavior.
import React from "react";
import { createRoot } from "react-dom/client";

const t0 = Date.now() - 600000;
const checks0 = [
  { id: "launch", title: "Launches a mob", steps: "hit", expect: "upward velocity above 1.0" },
  { id: "cooldown", title: "Respects the cooldown", steps: "hit twice", expect: "second hit does nothing" },
];
const verdict = (checks, fail) => ({
  finished: true, passed: !fail, serverErrors: [],
  checks: checks.map((c, i) => ({ id: c.id, status: fail && i === 0 ? "fail" : "pass", observed: fail && i === 0 ? "max velocity 0.4" : "matched" })),
});
const sess = (role, turn, extra = {}) => ({ role, turn, model: "opus", startedAt: t0, endedAt: t0 + 30000, usage: { costUsd: 0.4 }, sessionId: `s-${role}-${turn}`, ...extra });

const mod = {
  id: "mod_a", prompt: "A sword that launches mobs into the sky.", name: "SkyBlade", seed: false, status: "passed", phase: "done",
  createdAt: t0, updatedAt: t0, running: false, loadable: true, repoDir: "C:/x/skyblade", partners: {},
  spec: { summary: "Launches mobs.", behavior: ["launch"] }, testPlan: { checks: checks0 },
  turns: [{ prompt: "A sword that launches mobs into the sky.", at: t0, summary: "Launches mobs.", checks: checks0, status: "passed", endPhase: "done" }],
  sessions: [sess("spec", 0)],
  attempts: [
    { n: 1, turn: 0, role: "builder", status: "failed", startedAt: t0, sessions: [sess("builder", 0)], verdict: verdict(checks0, true), failure: { kind: "playtest", summary: "launch: max velocity 0.4" } },
    { n: 2, turn: 0, role: "fixer", status: "passed", startedAt: t0, sessions: [sess("fixer", 0)], verdict: verdict(checks0, false), lesson: "Apply velocity on the next tick." },
  ],
  error: null,
};
const feed = [
  { at: t0, role: "benana", kind: "phase", phase: "spec", text: "Writing the spec and an in-game test plan" },
  { at: t0 + 1, attempt: 0, role: "spec", kind: "text", text: "Planning two checks." },
  { at: t0 + 2, role: "spec", kind: "plan", text: "2 checks: Launches a mob · Respects the cooldown" },
  { at: t0 + 3, role: "benana", kind: "phase", phase: "build", text: "Attempt 1: writing SkyBlade" },
  { at: t0 + 4, attempt: 1, role: "builder", kind: "tool", name: "Write", summary: '{"file_path":"SkyBlade.java"}' },
  { at: t0 + 5, attempt: 1, role: "benana", kind: "failure", text: "Attempt 1 failed (playtest): launch: max velocity 0.4" },
  { at: t0 + 6, role: "benana", kind: "phase", phase: "fix", text: "Attempt 2: fixing what the playtester found" },
  { at: t0 + 7, role: "benana", kind: "phase", phase: "done", text: "SkyBlade passed after 2 attempts" },
];

const listeners = new Map();
const emit = (ch, data) => (listeners.get(ch) || []).forEach((fn) => fn(structuredClone(data)));
const calls = [];
window.__calls = calls;
const later = (ms, fn) => setTimeout(fn, ms);

function revise(prompt) {
  const checks1 = [checks0[0], { id: "ignite", title: "Sets the mob on fire", steps: "hit", expect: "mob on fire" }];
  const k = mod.turns.length;
  mod.turns.push({ prompt, at: Date.now(), revision: true });
  Object.assign(mod, { status: "queued", phase: "queued", running: true });
  const item = { at: Date.now(), role: "user", kind: "user", turn: k, text: prompt };
  feed.push(item);
  emit("studio:feed", { modId: mod.id, item });
  emit("studio:mod", mod);
  const push = (entry) => { const it = { at: Date.now(), ...entry }; feed.push(it); emit("studio:feed", { modId: mod.id, item: it }); };
  const phase = (p, text) => { mod.phase = p; push({ role: "benana", kind: "phase", phase: p, text }); emit("studio:mod", mod); };
  later(600, () => { mod.status = "running"; phase("spec", "Updating the spec and test plan for your change"); });
  later(1800, () => {
    Object.assign(mod.turns[k], { summary: "Launches mobs and sets them on fire.", checks: checks1 });
    mod.testPlan = { checks: checks1 };
    mod.sessions.push(sess("spec", k));
    push({ attempt: 0, role: "spec", kind: "plan", text: "2 checks: Launches a mob · Sets the mob on fire" });
    emit("studio:mod", mod);
  });
  later(2600, () => {
    mod.attempts.push({ n: 3, turn: k, revision: true, role: "builder", status: "running", startedAt: Date.now(), sessions: [sess("builder", k, { endedAt: null })] });
    phase("build", "Attempt 3: changing SkyBlade");
    push({ attempt: 3, role: "builder", kind: "tool", name: "Edit", summary: '{"file_path":"SkyBlade.java"}' });
  });
  later(4200, () => phase("playtest", "Attempt 3: the AI player is testing SkyBlade in-game"));
  later(6000, () => {
    const a = mod.attempts.at(-1);
    Object.assign(a, { status: "passed", verdict: verdict(checks1, false) });
    Object.assign(mod, { status: "passed", running: false });
    mod.turns[k].status = "passed";
    phase("done", "SkyBlade passed every check on the first attempt");
    mod.turns[k].endPhase = "done";
    emit("studio:mod", mod);
  });
  return mod;
}

window.benana = {
  invoke: async (channel, payload) => {
    calls.push([channel, payload]);
    const ok = (data) => ({ ok: true, data: structuredClone(data) });
    switch (channel) {
      case "studio:list": return ok([mod]);
      case "studio:get": return ok({ ...mod, feed });
      case "studio:revise": return ok(revise(payload.prompt));
      case "studio:create": return { ok: false, error: "harness: unexpected studio:create (a new mod would have been created)" };
      case "studio:lessons": return ok([]);
      case "game:status": return ok({ server: "running", bot: "online", version: "1.21.4" });
      case "app:code": return ok({ stale: false, changed: [], restartable: false });
      default: return ok(null);
    }
  },
  on: (channel, fn) => {
    listeners.set(channel, [...(listeners.get(channel) || []), fn]);
    return () => listeners.set(channel, (listeners.get(channel) || []).filter((f) => f !== fn));
  },
};

const { default: ModStudio } = await import("./components/studio/ModStudio.jsx");
createRoot(document.getElementById("root")).render(<ModStudio onOpenWorkspace={() => {}} />);

